"""Reviewer follow-up (read-only): authored corner-normal deviation on the cheek top faces, final against the P14 checkpoint."""
import importlib.util, json, math, os, sys
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__))
def load(n, p):
    s = importlib.util.spec_from_file_location(n, p); m = importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
out = {}
for tag, path, tops in (('final', 'helper.py', {'ctl.cheeks#0': [62, 63, 64, 65], 'ctl.cheeks#1': [75, 76, 77, 78]}),
                        ('p14', os.path.join('p14', 'helper_p14.py'), {'ctl.cheeks#0': [58, 59, 60, 61], 'ctl.cheeks#1': [69, 70, 71, 72]})):
    H = load(tag + '_helper', os.path.join(HERE, path))
    parts, _ = H.build_all()
    p = parts['ctl_body__shell']
    cn = H.corner_normals(p); fn = H._face_normals(p)
    res = {}
    for gid, faces in tops.items():
        for fi in faces:
            devs = [math.degrees(math.acos(max(-1, min(1, float(np.dot(cn[(fi, v)], fn[fi])))))) for v in p.f[fi][0]]
            res[f'{gid}/face{fi}'] = dict(cls=p.cls[fi], run=p.runs[fi], cornerDeviationDeg=[round(d, 2) for d in devs])
    out[tag] = res
    if tag == 'final':
        out['faceTupleSample'] = repr(p.f[62])[:200]
json.dump(out, sys.stdout, indent=1)
